/*
 * Two Windows
 * Generated by PRG32-Construction-Kit from the saved Blocks JSON.
 * Edit the blocks, then regenerate this file.
 *
 * HOW TO READ THIS FILE
 * A PRG32 cartridge is a small program that the PRG32 firmware loads into memory
 * and calls through three functions (the 'cartridge lifecycle'):
 *   tw_init()    once, when the game starts ('when game starts' blocks);
 *   tw_update()  once per frame, to move things ('every frame' blocks);
 *   tw_draw()    once per frame, after update, to paint the screen ('draw' blocks).
 * The file has five parts: 1 constants, 2 kit helper functions, 3 pictures,
 * 4 game state (the variables), 5 the three lifecycle functions.
 * Above every block's code a comment repeats the block in words; beside many lines
 * a second comment explains that line.
 *
 * RULES THIS C FOLLOWS
 * - Freestanding C99: no standard library (no printf, no malloc), because a
 *   cartridge runs without an operating system. Everything it needs is either in
 *   the firmware (functions named prg32_...) or written below in part 2.
 * - Every number is a 32-bit whole number (int). There is no floating point:
 *   7 / 2 is 3, and fractions are made with scaled numbers (256 means 1.0).
 * - The same blocks always produce exactly the same file.
 */
#include <stdint.h>                                     /* exact-size types: uint8_t, int16_t, uint32_t, ... */
#include "prg32.h"                                      /* the PRG32 firmware functions and constants */

/* ==========================================================================
 * 1. CONSTANTS
 * #define gives a name to a number. #ifndef ... #endif defines the name only when
 * prg32.h has not already done so. Colours are RGB565 numbers: 16 bits holding
 * 5 bits of red, 6 of green and 5 of blue.
 * ========================================================================== */
#ifndef PRG32_COLOR_BLACK
#define PRG32_COLOR_BLACK 0x0000                        /* red 0/31, green 0/63, blue 0/31 */
#endif
#ifndef PRG32_COLOR_WHITE
#define PRG32_COLOR_WHITE 0xFFFF                        /* red 31/31, green 63/63, blue 31/31 */
#endif
#ifndef PRG32_COLOR_RED
#define PRG32_COLOR_RED 0xF800                          /* red 31/31, green 0/63, blue 0/31 */
#endif
#ifndef PRG32_COLOR_GREEN
#define PRG32_COLOR_GREEN 0x07E0                        /* red 0/31, green 63/63, blue 0/31 */
#endif
#ifndef PRG32_COLOR_BLUE
#define PRG32_COLOR_BLUE 0x001F                         /* red 0/31, green 0/63, blue 31/31 */
#endif
#ifndef PRG32_COLOR_YELLOW
#define PRG32_COLOR_YELLOW 0xFFE0                       /* red 31/31, green 63/63, blue 0/31 */
#endif
#ifndef PRG32_COLOR_CYAN
#define PRG32_COLOR_CYAN 0x07FF                         /* red 0/31, green 63/63, blue 31/31 */
#endif
#ifndef PRG32_COLOR_MAGENTA
#define PRG32_COLOR_MAGENTA 0xF81F                      /* red 31/31, green 0/63, blue 31/31 */
#endif
#ifndef PRG32_COLOR_ORANGE
#define PRG32_COLOR_ORANGE 0xFD20                       /* red 31/31, green 41/63, blue 0/31 */
#endif
#ifndef PRG32_COLOR_PINK
#define PRG32_COLOR_PINK 0xFE19                         /* red 31/31, green 48/63, blue 25/31 */
#endif
#ifndef PRG32_COLOR_GRAY
#define PRG32_COLOR_GRAY 0x8410                         /* red 16/31, green 32/63, blue 16/31 */
#endif
#ifndef PRG32_COLOR_DARK_GRAY
#define PRG32_COLOR_DARK_GRAY 0x4208                    /* red 8/31, green 16/63, blue 8/31 */
#endif
#ifndef PRG32_COLOR_BROWN
#define PRG32_COLOR_BROWN 0xA145                        /* red 20/31, green 10/63, blue 5/31 */
#endif
#ifndef PRG32_COLOR_PURPLE
#define PRG32_COLOR_PURPLE 0x780F                       /* red 15/31, green 0/63, blue 15/31 */
#endif
#ifndef PRG32_COLOR_NAVY
#define PRG32_COLOR_NAVY 0x000F                         /* red 0/31, green 0/63, blue 15/31 */
#endif
#ifndef PRG32_COLOR_LIME
#define PRG32_COLOR_LIME 0x87E0                         /* red 16/31, green 63/63, blue 0/31 */
#endif
#ifndef PRG32_SCREEN_W
#define PRG32_SCREEN_W PRG32_GAME_W                     /* the game area is 320 pixels wide */
#endif
#ifndef PRG32_SCREEN_H
#define PRG32_SCREEN_H PRG32_GAME_H                     /* and 200 pixels high; (0, 0) is the top-left */
#endif

/* ==========================================================================
 * 2. KIT HELPER FUNCTIONS
 * Small functions the blocks need, written here so nothing is hidden.
 * Only the helpers this game uses are included. 'static' keeps a name
 * private to this file.
 * ========================================================================== */
/*
 * prg32_kit_peer_value(index, what): one value about another player in the multiplayer room.
 * what = 0 gives x, 1 y, 2 the 'look' (sprite) number, 3 the flags, 4 the buttons, 5 the
 * player ID. When the player does not exist (for example when playing alone) the answer is 0.
 * The firmware fills a structure (a group of named values) that lives on the stack.
 */
static int prg32_kit_peer_value(int index, int what) {
    prg32_player_state_t peer;                          /* space for the other player's data */
    /* &peer is the address the firmware fills */
    if (prg32_multiplayer_get_peer(index, &peer) != 0) return 0;
    switch (what) {                                     /* pick one field of the structure */
        case 0: return peer.x;
        case 1: return peer.y;
        case 2: return peer.sprite;
        case 3: return peer.flags;
        case 4: return (int)peer.input;
        default: return (int)peer.player_id;
    }
}

/*
 * prg32_kit_peers(): how many other players are connected (0 when playing alone).
 */
static int prg32_kit_peers(void) { return prg32_multiplayer_get_peer_count(); }

/* x of player 'index' */
static int prg32_kit_peer_x(int index) { return prg32_kit_peer_value(index, 0); }

/* y of player 'index' */
static int prg32_kit_peer_y(int index) { return prg32_kit_peer_value(index, 1); }

/* look of player 'index' */
static int prg32_kit_peer_look(int index) { return prg32_kit_peer_value(index, 2); }

/* flags of player 'index' */
static int prg32_kit_peer_flags(int index) { return prg32_kit_peer_value(index, 3); }

/* buttons of player 'index' */
static int prg32_kit_peer_input(int index) { return prg32_kit_peer_value(index, 4); }

/* ID of player 'index' */
static int prg32_kit_peer_id(int index) { return prg32_kit_peer_value(index, 5); }

/*
 * prg32_kit_my_id(): the player ID the server gave this console, 0 while it is not in the room.
 */
static int prg32_kit_my_id(void) { return (int)prg32_multiplayer_local_player_id(); }

/*
 * prg32_kit_mp_join(room): ask for a place in the room, once.
 * Every firmware join forgets the other players, so a join block that runs
 * every frame would never see anyone. The static variable lets only the first one through.
 */
static int prg32_kit_mp_joined;                         /* 0 until the first join */
static void prg32_kit_mp_join(const char *room) {
    if (prg32_kit_mp_joined) return;                    /* already asked */
    prg32_kit_mp_joined = 1;
    /* 0 means 'asked', not 'in the room': see my_id() */
    prg32_multiplayer_join(room, PRG32_MP_FLAG_ENABLE);
}

/*
 * prg32_kit_stick_x(): how far the stick is tilted, -127 (left) to 127 (right), 0 at rest.
 * Without an analog stick the left and right buttons give -127 and 127.
 */
static int prg32_kit_stick_x(void) { return (int)prg32_input_axis_x(); }

/* ==========================================================================
 * 4. GAME STATE
 * Variables declared outside any function keep their values from one frame
 * to the next. Every variable is a whole number (int); a list is an array.
 * ========================================================================== */
static int player_x = 0;                                /* variable player_x, starts at 0 */
static int player_y = 60;                               /* variable player_y, starts at 60 */

/* ==========================================================================
 * 5. LIFECYCLE FUNCTIONS
 * The firmware calls these three functions; their names must start with
 * the entry prefix 'tw'. 'void' means: no inputs, no result.
 * ========================================================================== */
/*
 * tw_init(): runs once when the cartridge starts (and again on restart).
 * First every variable and list gets its starting value, then the
 * 'when game starts' blocks run.
 */
void tw_init(void) {
    player_x = 0;                                       /* player_x starts again from 0 */
    player_y = 60;                                      /* player_y starts again from 60 */
    /* Block "join multiplayer": ask the PRG32 Multiplayer Server for a place in this room. The
     * answer takes a moment: my_id() stays 0 until the server has said yes. */
    prg32_kit_mp_join("kit-two-windows");
}

/*
 * tw_update(): runs once per frame, before drawing.
 * Game rules go here: read the buttons, move things, test collisions, keep score.
 */
void tw_update(void) {
    /* Block "set player_x to 150 + stick_x()": work out 150 + stick_x(), then store the result in
     * player_x. */
    player_x = 150 + prg32_kit_stick_x();               /* C syntax: '=' stores the value on the right in the variable on the left */
    /* Block "set player_y to 60": store 60 in the variable player_y. */
    player_y = 60;
    /* Block "share my position": give the firmware x player_x, y player_y, look 7 and flags 3; it
     * sends them at the end of this frame's update. */
    prg32_multiplayer_set_local_state(player_x, player_y, 7, 3);
    /* Block "share my buttons": the other players read these buttons with peer_input(i). */
    prg32_multiplayer_set_input(prg32_input_read());
    prg32_multiplayer_tick();                           /* every frame: send our state, receive the others' */
}

/*
 * tw_draw(): runs once per frame, after update.
 * Only painting goes here: the screen shows the state that update computed.
 */
void tw_draw(void) {
    /* Block "clear screen": paint the whole 320 x 200 game area black. */
    prg32_gfx_clear(PRG32_COLOR_BLACK);                 /* a firmware call: the PRG32 firmware does the drawing */
    /* Block "draw rectangle": a filled 8 x 8 rectangle, top-left corner at (player_x, player_y),
     * yellow. */
    prg32_gfx_rect(player_x, player_y, 8, 8, PRG32_COLOR_YELLOW);
    /* Block "if peers() > 0": the inner blocks run only when the condition is true (not 0). */
    if (prg32_kit_peers() > 0) {                        /* C syntax: if (condition) { ... }; any value except 0 counts as true */
        /* Block "draw rectangle": a filled 8 x 8 rectangle, top-left corner at (peer_x(0),
         * peer_y(0) + 40), cyan. */
        prg32_gfx_rect(prg32_kit_peer_x(0), prg32_kit_peer_y(0) + 40, 8, 8, PRG32_COLOR_CYAN);
    }                                                   /* end of if (peers() > 0) */
    /* Block "if peer_look(0) == 7 && peer_flags(0) == 3": the inner blocks run only when the
     * condition is true (not 0). */
    if (prg32_kit_peer_look(0) == 7 && prg32_kit_peer_flags(0) == 3) {
        /* Block "draw rectangle": a filled 8 x 8 rectangle, top-left corner at (0, 0), green. */
        prg32_gfx_rect(0, 0, 8, 8, PRG32_COLOR_GREEN);
    }                                                   /* end of if (peer_look(0) == 7 && peer_flags(0) == 3) */
    /* Block "if peer_input(0) & 16": the inner blocks run only when the condition is true (not 0). */
    if (prg32_kit_peer_input(0) & 16) {
        /* Block "draw rectangle": a filled 8 x 8 rectangle, top-left corner at (16, 0), red. */
        prg32_gfx_rect(16, 0, 8, 8, PRG32_COLOR_RED);
    }                                                   /* end of if (peer_input(0) & 16) */
    /* Block "if my_id() != 0": the inner blocks run only when the condition is true (not 0). */
    if (prg32_kit_my_id() != 0) {
        /* Block "draw rectangle": a filled 8 x 8 rectangle, top-left corner at (32, 0), blue. */
        prg32_gfx_rect(32, 0, 8, 8, PRG32_COLOR_BLUE);
    }                                                   /* end of if (my_id() != 0) */
    /* Block "if peer_id(0) != 0 && peer_id(0) != my_id()": the inner blocks run only when the
     * condition is true (not 0). */
    if (prg32_kit_peer_id(0) != 0 && prg32_kit_peer_id(0) != prg32_kit_my_id()) {
        /* Block "draw rectangle": a filled 8 x 8 rectangle, top-left corner at (48, 0), magenta. */
        prg32_gfx_rect(48, 0, 8, 8, PRG32_COLOR_MAGENTA);
    }                                                   /* end of if (peer_id(0) != 0 && peer_id(0) != my_id()) */
}
